import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Атлас поставок', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Портал клиентов', quotaPercent: 88, status: 'active' },
  { id: 'p3', name: 'Аналитика продаж', quotaPercent: 100, status: 'over' },
  { id: 'p4', name: 'Мобильное приложение', quotaPercent: 15, status: 'paused' },
  { id: 'p5', name: 'Внутренний CRM', quotaPercent: 67, status: 'active' },
  { id: 'p6', name: 'Биллинг-система', quotaPercent: 93, status: 'over' },
  { id: 'p7', name: 'Служба поддержки', quotaPercent: 30, status: 'paused' },
  { id: 'p8', name: 'Логистика', quotaPercent: 55, status: 'active' },
  { id: 'p9', name: 'Складской учёт', quotaPercent: 21, status: 'paused' },
  { id: 'p10', name: 'Партнёрская сеть', quotaPercent: 78, status: 'active' },
  { id: 'p11', name: 'Финансовый отчёт', quotaPercent: 105, status: 'over' },
  { id: 'p12', name: 'Онбординг сотрудников', quotaPercent: 8, status: 'paused' },
];

const statusFilters: { value: ProjectStatus; label: string }[] = [
  { value: 'active', label: 'Активен' },
  { value: 'paused', label: 'Приостановлен' },
  { value: 'over', label: 'Превышена квота' },
];

const statusBadge: Record<ProjectStatus, { label: string; tone: 'success' | 'default' | 'danger' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'Приостановлен', tone: 'default' },
  over: { label: 'Превышена квота', tone: 'danger' },
};

const pageSize = 5;

export default function ProjectQuotaPanel() {
  const [activeFilters, setActiveFilters] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleFilter = (status: ProjectStatus) => {
    setActiveFilters((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveFilters([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeFilters.length === 0) return projects;
    return projects.filter((project) => activeFilters.includes(project.status));
  }, [activeFilters]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / pageSize));
  const safePage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice((safePage - 1) * pageSize, safePage * pageSize);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
      <div
        role="group"
        aria-label="Фильтры по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {statusFilters.map((filter) => {
          const isActive = activeFilters.includes(filter.value);
          return (
            <JxChip
              key={filter.value}
              active={isActive}
              removable={isActive}
              onClick={() => toggleFilter(filter.value)}
              onRemove={() => toggleFilter(filter.value)}
            >
              {filter.label}
            </JxChip>
          );
        })}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Проектов с таким статусом нет"
          message="Попробуйте снять часть фильтров, чтобы увидеть больше проектов."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                className="jx-table"
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-r)',
                  padding: 'var(--jx-r-sm)',
                  border: '1px solid var(--jx-border)',
                  borderRadius: 'var(--jx-r)',
                  background: 'var(--jx-surface)',
                }}
              >
                <span style={{ color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}>
                  {project.name}
                </span>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-r)' }}>
                  <JxProgressCircle value={Math.min(project.quotaPercent, 100)} showValue />
                  <JxBadge tone={statusBadge[project.status].tone}>
                    {statusBadge[project.status].label}
                  </JxBadge>
                </div>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

